        for(int i=1;i<=179;i++){var candidate=new RecommendationDecision.Candidate(i,"合成"+i,"在库","合成",List.of(),RecommendationDecision.Confirmation.CONFIRMED,RecommendationDecision.Confirmation.CONFIRMED,List.of(),List.of());candidates.add(candidate);decisions.add(new RecommendationDecision.Decision(candidate,RecommendationDecision.State.PASS,List.of(),List.of()));}
